<?php require_once __DIR__ . '/includes/auth.php'; $user=require_role(['owner','branch_manager','inventory_manager','accountant']); $pdo=db(); check_tenant_active($pdo); $tid=require_tenant(); $base=''; $active='inventory'; $pageTitle='Inventory & Purchases'; $bid=branch_id();
function q1(PDO $pdo,string $sql,array $a){ $s=$pdo->prepare($sql); $s->execute($a); return $s->fetchColumn(); }
function qa(PDO $pdo,string $sql,array $a): array { $s=$pdo->prepare($sql); $s->execute($a); return $s->fetchAll(); }

$branches=tenant_branches($pdo,$tid);
if (is_post()) { verify_csrf(); $act=$_POST['action']??'';
  try { $pdo->beginTransaction();
  if($act==='adjust'){ $qty=(float)$_POST['quantity']; $type=in_array($_POST['type']??'', ['in','out','adjustment'], true)?$_POST['type']:'adjustment';
    if(!empty($_POST['product_id'])){ $pdo->prepare('UPDATE products SET stock_quantity=stock_quantity+? WHERE id=? AND tenant_id=?')->execute([$qty,(int)$_POST['product_id'],$tid]); $pdo->prepare('INSERT INTO stock_movements(tenant_id,branch_id,product_id,type,quantity,reference,note,created_by,created_at) VALUES(?,?,?,?,?,?,?, ?,NOW())')->execute([$tid,$bid,(int)$_POST['product_id'],$type,$qty,'manual',trim($_POST['note']??''),$user['id']]); }
    elseif(!empty($_POST['ingredient_id'])){ $pdo->prepare('UPDATE ingredients SET stock_quantity=stock_quantity+? WHERE id=? AND tenant_id=?')->execute([$qty,(int)$_POST['ingredient_id'],$tid]); $pdo->prepare('INSERT INTO stock_movements(tenant_id,branch_id,ingredient_id,type,quantity,reference,note,created_by,created_at) VALUES(?,?,?,?,?,?,?, ?,NOW())')->execute([$tid,$bid,(int)$_POST['ingredient_id'],$type,$qty,'manual',trim($_POST['note']??''),$user['id']]); }
    flash('success','Stock adjusted.'); }
  elseif($act==='wastage'){ $qty=abs((float)$_POST['quantity']);
    if(!empty($_POST['product_id'])){ $pdo->prepare('UPDATE products SET stock_quantity=GREATEST(0,stock_quantity-?) WHERE id=? AND tenant_id=?')->execute([$qty,(int)$_POST['product_id'],$tid]); $pdo->prepare('INSERT INTO stock_movements(tenant_id,branch_id,product_id,type,quantity,reference,note,created_by,created_at) VALUES(?,?,?,?,"wastage",?,?,?,NOW())')->execute([$tid,$bid,(int)$_POST['product_id'],-$qty,'wastage',trim($_POST['note']??'Wastage'),$user['id']]); }
    elseif(!empty($_POST['ingredient_id'])){ $pdo->prepare('UPDATE ingredients SET stock_quantity=GREATEST(0,stock_quantity-?) WHERE id=? AND tenant_id=?')->execute([$qty,(int)$_POST['ingredient_id'],$tid]); $pdo->prepare('INSERT INTO stock_movements(tenant_id,branch_id,ingredient_id,type,quantity,reference,note,created_by,created_at) VALUES(?,?,?,?,"wastage",?,?,?,NOW())')->execute([$tid,$bid,(int)$_POST['ingredient_id'],-$qty,'wastage',trim($_POST['note']??'Wastage'),$user['id']]); }
    flash('success','Wastage recorded.'); }
  elseif($act==='ingredient_save'){ if(!empty($_POST['id'])) $pdo->prepare('UPDATE ingredients SET name=?,unit=?,stock_quantity=?,cost_per_unit=?,reorder_level=? WHERE id=? AND tenant_id=?')->execute([trim($_POST['name']),trim($_POST['unit']),(float)$_POST['stock_quantity'],(float)$_POST['cost_per_unit'],(float)$_POST['reorder_level'],(int)$_POST['id'],$tid]);
    else $pdo->prepare('INSERT INTO ingredients(tenant_id,name,unit,stock_quantity,cost_per_unit,reorder_level) VALUES(?,?,?,?,?,?)')->execute([$tid,trim($_POST['name']),trim($_POST['unit']),(float)$_POST['stock_quantity'],(float)$_POST['cost_per_unit'],(float)$_POST['reorder_level']]); flash('success','Ingredient saved.'); }
  elseif($act==='supplier_save'){ if(!empty($_POST['id'])) $pdo->prepare('UPDATE suppliers SET name=?,contact=?,email=?,phone=? WHERE id=? AND tenant_id=?')->execute([trim($_POST['name']),trim($_POST['contact']??''),trim($_POST['email']??''),trim($_POST['phone']??''),(int)$_POST['id'],$tid]);
    else $pdo->prepare('INSERT INTO suppliers(tenant_id,name,contact,email,phone) VALUES(?,?,?,?,?)')->execute([$tid,trim($_POST['name']),trim($_POST['contact']??''),trim($_POST['email']??''),trim($_POST['phone']??'')]); flash('success','Supplier saved.'); }
  elseif($act==='supplier_delete'){ $pdo->prepare('DELETE FROM suppliers WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]); flash('success','Supplier deleted.'); }
  elseif($act==='po_create'){ $pdo->prepare('INSERT INTO purchase_orders(tenant_id,branch_id,supplier_id,status,total,created_at) VALUES(?,?,?,"ordered",0,NOW())')->execute([$tid,(int)($_POST['branch_id']??$bid),(int)$_POST['supplier_id']]); $po=(int)$pdo->lastInsertId();
    $pdo->prepare('INSERT INTO purchase_items(tenant_id,purchase_order_id,ingredient_id,product_id,quantity,unit_cost) VALUES(?,?,?,?,?,?)')->execute([$tid,$po,!empty($_POST['ingredient_id'])?(int)$_POST['ingredient_id']:null,!empty($_POST['product_id'])?(int)$_POST['product_id']:null,(float)$_POST['quantity'],(float)$_POST['unit_cost']]);
    $pdo->prepare('UPDATE purchase_orders SET total=? WHERE id=?')->execute([(float)$_POST['quantity']*(float)$_POST['unit_cost'],$po]); flash('success','Purchase order created.'); }
  elseif($act==='po_receive'){ $po=(int)$_POST['id']; $items=qa($pdo,'SELECT * FROM purchase_items WHERE purchase_order_id=? AND tenant_id=?',[$po,$tid]);
    foreach($items as $it){ if($it['ingredient_id']) $pdo->prepare('UPDATE ingredients SET stock_quantity=stock_quantity+? WHERE id=? AND tenant_id=?')->execute([$it['quantity'],$it['ingredient_id'],$tid]);
      if($it['product_id']) $pdo->prepare('UPDATE products SET stock_quantity=stock_quantity+? WHERE id=? AND tenant_id=?')->execute([$it['quantity'],$it['product_id'],$tid]);
      $pdo->prepare('INSERT INTO stock_movements(tenant_id,branch_id,product_id,ingredient_id,type,quantity,reference,note,created_by,created_at) VALUES(?,?,?,?,"in",?,?,?,NOW())')->execute([$tid,$bid,$it['product_id'],$it['ingredient_id'],$it['quantity'],'PO #'.$po,'Purchase received',$user['id']]); }
    $pdo->prepare('UPDATE purchase_orders SET status="received", received_at=NOW() WHERE id=? AND tenant_id=?')->execute([$po,$tid]); flash('success','Purchase received — stock added.'); }
  $pdo->commit(); } catch(Throwable $ex){ if($pdo->inTransaction()) $pdo->rollBack(); flash('error','Action failed: '.$ex->getMessage()); }
  redirect('inventory.php'); }
$prods=qa($pdo,'SELECT * FROM products WHERE tenant_id=? AND track_stock=1 ORDER BY stock_quantity',[$tid]);
$ings=qa($pdo,'SELECT * FROM ingredients WHERE tenant_id=? ORDER BY stock_quantity',[$tid]);
$sups=qa($pdo,'SELECT * FROM suppliers WHERE tenant_id=? ORDER BY name',[$tid]);
$pos=qa($pdo,'SELECT po.*,s.name supplier FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id WHERE po.tenant_id=? ORDER BY po.id DESC LIMIT 20',[$tid]);
$moves=qa($pdo,'SELECT sm.*,p.name pname,i.name iname FROM stock_movements sm LEFT JOIN products p ON p.id=sm.product_id LEFT JOIN ingredients i ON i.id=sm.ingredient_id WHERE sm.tenant_id=? ORDER BY sm.id DESC LIMIT 15',[$tid]);
$lowProds=array_filter($prods, fn($r)=>(float)$r['stock_quantity']<=(float)$r['reorder_level']);
$lowIngs=array_filter($ings, fn($r)=>(float)$r['stock_quantity']<=(float)$r['reorder_level']);
include __DIR__ . '/includes/header.php'; ?>
<?php if($lowProds || $lowIngs): ?><div class="alert alert-warning"><strong>Low stock:</strong> <?php foreach($lowProds as $r) echo e($r['name']).' ('.$r['stock_quantity'].') · '; foreach($lowIngs as $r) echo e($r['name']).' ('.$r['stock_quantity'].' '.e($r['unit']).') · '; ?></div><?php endif; ?>
<div class="row g-3"><div class="col-lg-6"><div class="card p-3"><h6>Product stock</h6><table class="table table-sm mb-0"><tr><th>Product</th><th>Stock</th><th>Reorder ≤</th><th>Value</th></tr><?php foreach($prods as $r): ?><tr class="<?= (float)$r['stock_quantity']<=(float)$r['reorder_level']?'table-warning':'' ?>"><td><?= e($r['name']) ?></td><td><?= $r['stock_quantity'] ?></td><td><?= $r['reorder_level'] ?></td><td><?= money((float)$r['stock_quantity']*(float)$r['cost']) ?></td></tr><?php endforeach; ?></table></div>
<div class="card p-3 mt-3"><h6>Ingredients</h6><table class="table table-sm"><tr><th>Ingredient</th><th>Stock</th><th>Cost/unit</th></tr><?php foreach($ings as $r): ?><tr class="<?= (float)$r['stock_quantity']<=(float)$r['reorder_level']?'table-warning':'' ?>"><td><?= e($r['name']) ?></td><td><?= $r['stock_quantity'] ?> <?= e($r['unit']) ?></td><td><?= money($r['cost_per_unit']) ?></td></tr><?php endforeach; ?></table>
<form class="row g-2" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="ingredient_save"><div class="col-4"><input class="form-control form-control-sm" name="name" placeholder="Name" required></div><div class="col-2"><input class="form-control form-control-sm" name="unit" placeholder="kg" required></div><div class="col-2"><input class="form-control form-control-sm" type="number" step="0.01" name="stock_quantity" placeholder="Qty" required></div><div class="col-2"><input class="form-control form-control-sm" type="number" step="0.01" name="cost_per_unit" placeholder="Cost"></div><div class="col-2"><input class="form-control form-control-sm" type="number" step="0.01" name="reorder_level" placeholder="Reorder" value="10"></div><div class="col-12"><button class="btn btn-sm btn-primary">Add ingredient</button></div></form></div>
<div class="card p-3 mt-3"><h6>Adjust / wastage</h6><form class="row g-2" method="post"><?= csrf_field() ?>
<div class="col-6"><select class="form-select form-select-sm" name="product_id"><option value="">— product —</option><?php foreach($prods as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-6"><select class="form-select form-select-sm" name="ingredient_id"><option value="">— ingredient —</option><?php foreach($ings as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></div>
