<div class="col-lg-6"><div class="card p-3"><h6>Suppliers</h6><?php foreach($sups as $r): ?><div class="d-flex justify-content-between border-bottom py-2"><span><strong><?= e($r['name']) ?></strong> <span class="small text-muted"><?= e($r['phone']??'') ?> <?= e($r['email']??'') ?></span></span><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="supplier_delete"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div><?php endforeach; ?>
<form class="row g-2 mt-2" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="supplier_save"><div class="col-4"><input class="form-control form-control-sm" name="name" placeholder="Supplier" required></div><div class="col-3"><input class="form-control form-control-sm" name="contact" placeholder="Contact"></div><div class="col-3"><input class="form-control form-control-sm" name="phone" placeholder="Phone"></div><div class="col-2"><button class="btn btn-sm btn-primary w-100">Add</button></div><div class="col-12"><input class="form-control form-control-sm" name="email" placeholder="Email"></div></form></div>
