<div class="col-4"><select class="form-select form-select-sm" name="supplier_id"><?php foreach($sups as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-4"><select class="form-select form-select-sm" name="ingredient_id"><option value="">— ingredient —</option><?php foreach($ings as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-4"><select class="form-select form-select-sm" name="product_id"><option value="">— product —</option><?php foreach($prods as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-3"><select class="form-select form-select-sm" name="branch_id"><?php foreach($branches as $b): ?><option value="<?= $b['id'] ?>"><?= e($b['name']) ?></option><?php endforeach; ?></select></div>
