<div class="card p-3 mt-3"><h6>Recent stock movements</h6><table class="table table-sm mb-0"><tr><th>Item</th><th>Type</th><th>Qty</th><th>Note</th></tr><?php foreach($moves as $r): ?><tr><td><?= e($r['pname']??$r['iname']??'') ?></td><td><?= e($r['type']) ?></td><td><?= $r['quantity'] ?></td><td class="small"><?= e($r['note']??'') ?></td></tr><?php endforeach; ?></table></div></div></div>
